{
  "title": "functions.expression.ObjectInputSchema",
  "description": "Schema for an object input with named properties.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the object.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "properties": {
      "description": "Schema for each property in the object.",
      "type": "object",
      "additionalProperties": {
        "$ref": "functions.expression.InputSchema"
      }
    },
    "required": {
      "description": "List of property names that must be present.",
      "anyOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ObjectInputSchemaType"
    }
  }
}

{
  "title": "agent.completions.message.SimpleContentExpression",
  "description": "Expression variant of [`SimpleContent`] for dynamic content.",
  "anyOf": [
    {
      "title": "Text",
      "description": "Plain text content.",
      "type": "string"
    },
    {
      "title": "Parts",
      "description": "Multi-part text content expressions.",
      "type": "array",
      "items": {
        "description": "A value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
        "anyOf": [
          {
            "title": "Expression",
            "description": "An expression (JMESPath or Starlark) to evaluate.",
            "$ref": "functions.expression.Expression"
          },
          {
            "title": "Value",
            "description": "A literal value.",
            "$ref": "agent.completions.message.SimpleContentPartExpression"
          }
        ]
      }
    }
  ]
}

{
  "title": "agent.completions.message.MessageExpression",
  "description": "A message with expressions for dynamic content.\n\nThis is the expression variant of [`Message`] used in function definitions\nwhere message content can be computed from the function input at runtime.\nSupports both JMESPath and Starlark expressions.",
  "anyOf": [
    {
      "title": "Developer",
      "type": "object",
      "$ref": "agent.completions.message.DeveloperMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "developer"
          ]
        }
      }
    },
    {
      "title": "System",
      "type": "object",
      "$ref": "agent.completions.message.SystemMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "system"
          ]
        }
      }
    },
    {
      "title": "User",
      "type": "object",
      "$ref": "agent.completions.message.UserMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "user"
          ]
        }
      }
    },
    {
      "title": "Assistant",
      "type": "object",
      "$ref": "agent.completions.message.AssistantMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "assistant"
          ]
        }
      }
    },
    {
      "title": "Tool",
      "type": "object",
      "$ref": "agent.completions.message.ToolMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "tool"
          ]
        }
      }
    }
  ]
}

{
  "title": "agent.completions.message.SimpleContentPartExpression",
  "description": "A text part expression.",
  "type": "object",
  "properties": {
    "text": {
      "description": "The text expression.\n\nA value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
      "anyOf": [
        {
          "title": "Expression",
          "description": "An expression (JMESPath or Starlark) to evaluate.",
          "$ref": "functions.expression.Expression"
        },
        {
          "title": "Value",
          "description": "A literal value.",
          "type": "string"
        }
      ]
    },
    "type": {
      "type": "string",
      "enum": [
        "text"
      ]
    }
  }
}

